<script lang="ts">
 import { db } from '$lib/db';import { onMount } from 'svelte';let counts=$state({drawings:0,stages:0,sets:0}),error=$state(''),message=$state('');
 async function refresh(){counts={drawings:await db.drawings.count(),stages:await db.stages.count(),sets:await db.paletteSets.count()};}
 onMount(()=>{void refresh();});
 function toBase64(blob:Blob):Promise<string>{return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('Could not read image data'));reader.readAsDataURL(blob);});}
 async function backup(){error='';try{const [drawings,stages,paletteSets]=await Promise.all([db.drawings.toArray(),db.stages.toArray(),db.paletteSets.toArray()]),packed=await Promise.all(stages.map(async s=>({...s,originalBlob:await toBase64(s.originalBlob),flatBlob:await toBase64(s.flatBlob),originalType:s.originalBlob.type,flatType:s.flatBlob.type}))),data={format:'skepanion-backup-v1',exportedAt:Date.now(),drawings,stages:packed,paletteSets},blob=new Blob([JSON.stringify(data)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`skepanion-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(url);message='Backup downloaded.';}catch(e){error=e instanceof Error?e.message:'Backup could not be created.';}}
 function fromBase64(value:string,type:string):Blob{const raw=atob(value),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);return new Blob([bytes],{type});}
 async function restore(file?:File){if(!file)return;error='';message='';try{const data=JSON.parse(await file.text()) as {format:string;drawings:unknown[];paletteSets:unknown[];stages:Array<Record<string,unknown>&{originalBlob:string;flatBlob:string;originalType:string;flatType:string}>};if(data.format!=='skepanion-backup-v1'||!Array.isArray(data.drawings)||!Array.isArray(data.stages)||!Array.isArray(data.paletteSets))throw new Error('This is not a valid Skepanion backup.');if(!confirm('Importing replaces all Skepanion data currently stored on this device. Continue?'))return;const stages=data.stages.map(s=>({...s,originalBlob:fromBase64(s.originalBlob,s.originalType),flatBlob:fromBase64(s.flatBlob,s.flatType)}));await db.transaction('rw',db.drawings,db.stages,db.paletteSets,async()=>{await Promise.all([db.drawings.clear(),db.stages.clear(),db.paletteSets.clear()]);await db.drawings.bulkAdd(data.drawings as never[]);await db.stages.bulkAdd(stages as never[]);await db.paletteSets.bulkAdd(data.paletteSets as never[]);});message='Backup restored.';await refresh();}catch(e){error=e instanceof Error?e.message:'Backup could not be imported.';}}
</script>
<div class="app"><header class="topbar"><a class="brand" href="/"><span class="brand-mark">✳</span>Skepanion</a><nav class="nav"><a href="/">Drawings</a></nav></header><p class="eyebrow">Your data, in your hands</p><h1>Backup and restore</h1><p class="muted">Your sketchbook lives in this browser. Save a backup file somewhere safe so you can bring it to another device or restore it later.</p>
<section class="section card"><h2>Stored on this device</h2><p class="muted">{counts.drawings} drawings · {counts.stages} stages · {counts.sets} color sets</p><div class="row"><button class="button" onclick={()=>void backup()}>↓ Download backup</button><label class="button secondary" for="restore-file">↑ Import backup</label><input id="restore-file" type="file" accept="application/json,.json" class="sr-only" onchange={(e)=>void restore(e.currentTarget.files?.[0])}/></div>{#if message}<p role="status">{message}</p>{/if}{#if error}<p role="alert" style="color:#a33">{error}</p>{/if}</section><p class="muted">Importing a backup replaces the data stored in this browser.</p></div>
